-- Ficha de Cuto Estévez.
--
-- La biografía de relleno era completamente genérica, sin nombrar canción, orquesta ni hecho
-- real de su carrera como trompetista fundador de la Billo's Caracas Boys y autor de «Todo
-- Me Gusta de Ti».
-- middle_name corregido de "Elias Elíseo" a "Elías Elisio" (grafía de la fuente periodística).
-- primary_genre corregido de merengue a bolero. occupations ampliado con bandleader y music
-- educator.

UPDATE artists SET middle_name = 'Elías Elisio', primary_genre = 'bolero',
       occupations = '["composer","conductor","bandleader","music educator"]'::jsonb
       WHERE slug = 'cuto-estevez';

